// Category A — a tile that acts when pressed: an icon, a label and an optional second line, the whole
// tile the press target. A payment product draws its payment methods this way (a POS's 결제하기 tiles,
// a kiosk's method screen), and call-method and settings choices reuse the shape. A press acts at once; nothing stays selected, which is
// why this is a Button and not a radio card (component-usage.md § Product grids, the same fork).
//
// `orientation` lays it out: `vertical` stacks the icon above the label (a tile in a grid), and
// `horizontal` puts the icon before the text (a row in a list, as on a phone).
//
// A disabled tile is skipped by the keyboard and dimmed, so its reason belongs in `description`
// (「프런트 연결 필요」): the second line is then read as part of the tile's name wherever it is reached.
//
// `variant="media"` is the tile a shop home leads with (「주간 TOP 20」, an appliance tile): a white
// card with a decorative edge whose top is a tinted band holding the icon or a product picture, the
// title and caption below. It is a variant HERE, not a ProductTile prop and not a Block, because:
// - it is still an action, not a product: pressing it navigates (「상품 보러가기」), it carries no price
//   and adds nothing to an order, which is the ActionTile side of component-usage.md § Product grids;
// - it is ONE press target with one look, and a Block composes Components without owning the box of
//   one Button: the band would have to live inside a Button the Block does not draw;
// - the anatomy (icon, label, description, the press) is ActionTile's; only the paper and where the
//   icon sits change.
// The word: no vocabulary axis names "leads with a full-width media region", and the field words
// (`filled` · `outline`) name only the box, which would leave the band unsaid. `media` is the part
// dictionary's word for exactly that region (component-vocabulary.md § Part dictionary), so the
// variant is named after the anatomy it adds; the resting tile is `filled`, the field word for a
// borderless box on a neutral fill, which is what it already drew.
// The media tile is a surface (white, edged, card-shaped), so its corner and text inset are the
// surface pair at the size's tier, where the filled tile is a key on the general ladder. A media tile
// always stacks: a band across the top has no horizontal form, so `orientation` does not apply to it.
import { Button as AriaButton } from "react-aria-components";
import type { ButtonProps as AriaButtonProps } from "react-aria-components";
import type { CSSProperties, ReactNode, Ref } from "react";
import "./ActionTile.css";

type ActionTileSize = "small" | "medium" | "large";

export interface ActionTileProps
  extends Omit<AriaButtonProps, "className" | "style" | "children" | "isDisabled" | "onPress"> {
  /**
   * `filled`: a borderless tile on a neutral fill, as a payment method tile is drawn. `media`: a white
   * edged card whose top is a tinted band holding the icon or a product picture, the title and
   * caption below.
   *
   * @default "filled"
   */
  variant?: "filled" | "media";
  /**
   * Size axis: the type rung, the inset and the minimum height.
   *
   * @default "medium"
   */
  size?: ActionTileSize;
  /**
   * `vertical`: the icon above the label, a tile in a grid. `horizontal`: the icon before the text, a
   * row in a list. A `media` tile always stacks, since its band runs across the top.
   *
   * @default "vertical"
   */
  orientation?: "vertical" | "horizontal";
  /**
   * A vertical tile's alignment: `center` (a counter screen, a re-pay modal) or `start` (a POS 결제하기
   * grid). A horizontal tile always starts.
   *
   * @default "center"
   */
  align?: "center" | "start";
  /**
   * The icon, decorative: the label names the action. Pass it with `aria-hidden` at `size="1em"`. In a
   * `media` tile it may instead be a product picture, an `<img alt="">` sized to fit the band; the band
   * centres it and clips anything taller.
   */
  icon?: ReactNode;
  /** What pressing does, e.g. "신용카드". */
  label: ReactNode;
  /** A second line, e.g. "간편결제·지역화폐", or why a disabled tile cannot be pressed. */
  description?: ReactNode;
  /**
   * `media` only: a caption set in the band under the icon, e.g. "정수기". Read as part of the tile's
   * name, before the label.
   */
  mediaCaption?: ReactNode;
  /** When true the tile cannot be pressed. Say why in `description`. */
  isDisabled?: boolean;
  /** Called when the tile is pressed. */
  onPress?: () => void;
  /** Additional class (optional). sd-action-tile is always preserved. */
  className?: string;
  /** Inline style for layout, e.g. a grid placement. */
  style?: CSSProperties;
  /** Forwarded to the button element. */
  ref?: Ref<HTMLButtonElement>;
}

export function ActionTile({
  variant = "filled",
  size = "medium",
  orientation = "vertical",
  align = "center",
  icon,
  label,
  description,
  mediaCaption,
  isDisabled = false,
  onPress,
  className,
  ref,
  ...props
}: ActionTileProps) {
  const iconSlot = icon != null && (
    <span className="sd-action-tile__icon" data-size={size} aria-hidden="true">
      {icon}
    </span>
  );
  return (
    <AriaButton
      {...props}
      ref={ref}
      data-variant={variant}
      data-size={size}
      data-orientation={variant === "media" ? "vertical" : orientation}
      data-align={align}
      isDisabled={isDisabled}
      onPress={onPress}
      className={className ? `sd-action-tile ${className}` : "sd-action-tile"}
    >
      {variant === "media" ? (
        <span className="sd-action-tile__media">
          {iconSlot}
          {mediaCaption != null && <span className={`sd-type-caption-${size}`}>{mediaCaption}</span>}
        </span>
      ) : (
        iconSlot
      )}
      <span className="sd-action-tile__text" data-variant={variant}>
        <span className={`sd-action-tile__label sd-type-body-${size}-emphasized`}>{label}</span>
        {description != null && (
          <span className={`sd-action-tile__description sd-type-caption-${size}`}>{description}</span>
        )}
      </span>
    </AriaButton>
  );
}

/* A filled tile with no edge of its own, as a payment method tile is drawn: vertical centres the icon
   over the text in the tile (a method grid); horizontal sets the icon before the text in a row. */
.sd-action-tile {
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sd-action-tile-gap);
  inline-size: 100%;
  margin: 0;
  border: none;
  background: var(--sd-action-tile-background);
  color: var(--sd-action-tile-label-foreground);
  text-align: center;
  cursor: pointer;
  outline: none;
  /* The wash each state lays over this part: the surface wash, or over a fill the one named for that
     fill, which goes away from its inks (contrast-contract.mjs § the state layer over a fill). */
  --sd-action-tile-state-hover-current: var(--sd-state-hover-neutral-subtle);
  --sd-action-tile-state-pressed-current: var(--sd-state-pressed-neutral-subtle);
}

.sd-action-tile[data-align="start"] {
  align-items: start;
  justify-content: start;
  text-align: start;
}

.sd-action-tile[data-orientation="horizontal"] {
  flex-direction: row;
  align-items: center;
  justify-content: start;
  text-align: start;
}

.sd-action-tile[data-size="small"] {
  padding: var(--sd-action-tile-padding-small);
  border-radius: var(--sd-action-tile-radius-small);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-action-tile[data-size="medium"] {
  padding: var(--sd-action-tile-padding-medium);
  border-radius: var(--sd-action-tile-radius-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
}
.sd-action-tile[data-size="large"] {
  padding: var(--sd-action-tile-padding-large);
  border-radius: var(--sd-action-tile-radius-large);
  corner-shape: superellipse(var(--sd-radius-curve));
}

/* Only a tile in a grid holds a minimum height; a row in a list hugs its text. */
.sd-action-tile[data-orientation="vertical"][data-size="small"] {
  min-block-size: var(--sd-action-tile-min-height-small);
}
.sd-action-tile[data-orientation="vertical"][data-size="medium"] {
  min-block-size: var(--sd-action-tile-min-height-medium);
}
.sd-action-tile[data-orientation="vertical"][data-size="large"] {
  min-block-size: var(--sd-action-tile-min-height-large);
}

.sd-action-tile::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  /* Under the content, over the fill: the root isolates, so -1 stays inside it (component-contract.md § 6). */
  z-index: -1;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-action-tile[data-hovered]::after {
  background: var(--sd-action-tile-state-hover-current);
}
.sd-action-tile[data-pressed]::after {
  background: var(--sd-action-tile-state-pressed-current);
}
.sd-action-tile[data-focus-visible] {
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-action-tile[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

.sd-action-tile__icon {
  display: inline-flex;
  flex: 0 0 auto;
  color: var(--sd-action-tile-icon-foreground);
}
.sd-action-tile__icon[data-size="small"] {
  font-size: var(--sd-action-tile-icon-size-small);
}
.sd-action-tile__icon[data-size="medium"] {
  font-size: var(--sd-action-tile-icon-size-medium);
}
.sd-action-tile__icon[data-size="large"] {
  font-size: var(--sd-action-tile-icon-size-large);
}

.sd-action-tile__text {
  display: flex;
  flex-direction: column;
  gap: var(--sd-action-tile-text-gap);
  min-inline-size: 0;
}

.sd-action-tile__label {
  overflow-wrap: anywhere;
}

.sd-action-tile__description {
  color: var(--sd-action-tile-description-foreground);
}

/* media: a white, edged card whose top is a tinted band holding the picture, the title and caption
   below on the paper. The band is painted as a background layer of the tile itself, not by the band
   element, so the ::after state wash (z-index -1, under the content) lays over the band too and the
   ink stays above the wash. The band element only reserves the height and centres the picture. */
.sd-action-tile[data-variant="media"] {
  justify-content: start;
  gap: 0;
  padding: 0;
  border: var(--sd-action-tile-border-width-media) solid var(--sd-action-tile-border-media);
  background:
    linear-gradient(var(--sd-action-tile-media-background), var(--sd-action-tile-media-background)) top / 100% var(--sd-action-tile-media-height-current) no-repeat,
    var(--sd-action-tile-background-media);
  /* The wash is the band fill's own (it goes away from the band's brand ink); over the white body it
     reads as the same faint tint, so one wash serves the whole tile. */
  --sd-action-tile-state-hover-current: var(--sd-state-hover-brand-subtle);
  --sd-action-tile-state-pressed-current: var(--sd-state-pressed-brand-subtle);
}
/* One surface tier per size: the corner and the inset are a pair (token-contract.md § By geometry). */
.sd-action-tile[data-variant="media"][data-size="small"] {
  border-radius: var(--sd-action-tile-radius-media-small);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-action-tile-media-height-current: var(--sd-action-tile-media-height-small);
  --sd-action-tile-padding-media-current: var(--sd-action-tile-padding-media-small);
}
.sd-action-tile[data-variant="media"][data-size="medium"] {
  border-radius: var(--sd-action-tile-radius-media-medium);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-action-tile-media-height-current: var(--sd-action-tile-media-height-medium);
  --sd-action-tile-padding-media-current: var(--sd-action-tile-padding-media-medium);
}
.sd-action-tile[data-variant="media"][data-size="large"] {
  border-radius: var(--sd-action-tile-radius-media-large);
  corner-shape: superellipse(var(--sd-radius-curve));
  --sd-action-tile-media-height-current: var(--sd-action-tile-media-height-large);
  --sd-action-tile-padding-media-current: var(--sd-action-tile-padding-media-large);
}

.sd-action-tile__media {
  display: flex;
  flex-direction: column;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: var(--sd-action-tile-media-gap);
  align-self: stretch;
  box-sizing: border-box;
  block-size: var(--sd-action-tile-media-height-current);
  padding-inline: var(--sd-action-tile-padding-media-current);
  overflow: hidden;
  color: var(--sd-action-tile-media-foreground);
  text-align: center;
}

.sd-action-tile__text[data-variant="media"] {
  align-self: stretch;
  padding: var(--sd-action-tile-padding-media-current);
}
